// ============================================================
// 整件-尺寸测量 完整示例
// 流程: 基准线(左/右两段, 中间被遮挡) -> 工件左/右线 -> 边缘交点(基准线左/右点) -> 顶点
//   高度 = 顶点到基准线的点到线距离
//   中垂线 = 基准线中点处的垂线; 左/右距离 = 左/右线中点到中垂线距离
//   宽度 = 左线中点到右线的垂直距离(点到线)
//   对称度 = |左距离 - 右距离|
//   毫米 = 像素距离 × 系数管理器的像素精度(面N_像素精度)
// 返回结果字典会发送到 PLC 与 MQTT。
// 注意: ROI 坐标为示例值, 请用 ROI 编辑器按实际工件框选后替换!
// ============================================================
function process(image) {
    var faceNo = 1   // 当前面号(1~4), 决定读取哪一面的像素精度系数

    // 1. 找底板基准线: 中间被遮挡, 分左、右两段分别查找(水平边 -> 垂直扫描 "V")
    var baseLineL = FindLine(1500, 5200, 2200, 400, "V", "W2B", 30, 40, "first", 5)
    var baseLineR = FindLine(5600, 5200, 2200, 400, "V", "W2B", 30, 40, "first", 5)
    // 2. 找工件左线 / 右线(垂直边 -> 水平扫描 "H"; 极性按实际明暗可能要翻转)
    var leftLine  = FindLine(1500, 2000, 500, 3500, "H", "B2W", 30, 40, "first", 5)
    var rightLine = FindLine(7300, 2000, 500, 3500, "H", "W2B", 30, 40, "first", 5)
    // 3. 找产品顶点(自上而下首个白到黑边缘)
    var vertex = FindVertex(3000, 500, 3300, 2000, 20, 60)

    if (!baseLineL.found || !baseLineR.found || !leftLine.found || !rightLine.found || !vertex.found) {
        return { ok: false, message: "特征查找失败: 基准线(左/右)/左右线/顶点未全部找到" }
    }

    // 4. 合成基准线: 两段方向取平均并归一化(理论上共线), 锚点取两段锚点中点
    var baseDx = baseLineL.dx + baseLineR.dx
    var baseDy = baseLineL.dy + baseLineR.dy
    var baseLen = Math.sqrt(baseDx * baseDx + baseDy * baseDy)
    baseDx = baseDx / baseLen
    baseDy = baseDy / baseLen
    var basePx = (baseLineL.px + baseLineR.px) / 2
    var basePy = (baseLineL.py + baseLineR.py) / 2

    // 5. 边缘交点: 左段基准线与左线交点=基准线左点; 右段基准线与右线交点=基准线右点
    var baseLeft = EdgeIntersect(baseLineL.px, baseLineL.py, baseLineL.dx, baseLineL.dy,
                                 leftLine.px, leftLine.py, leftLine.dx, leftLine.dy)
    var baseRight = EdgeIntersect(baseLineR.px, baseLineR.py, baseLineR.dx, baseLineR.dy,
                                  rightLine.px, rightLine.py, rightLine.dx, rightLine.dy)
    if (!baseLeft.found || !baseRight.found) {
        return { ok: false, message: "基准线交点计算失败" }
    }

    // 6. 基准线的中垂线: 过基准线左/右点中点, 方向为基准线方向旋转90度 (-dy, dx)
    var midX = (baseLeft.x + baseRight.x) / 2
    var midY = (baseLeft.y + baseRight.y) / 2
    var perpDx = -baseDy
    var perpDy =  baseDx

    // 7. 像素距离
    var heightPx = PointToLine(vertex.x, vertex.y, basePx, basePy, baseDx, baseDy).distance
    var leftDistPx  = PointToLine(leftLine.px, leftLine.py, midX, midY, perpDx, perpDy).distance
    var rightDistPx = PointToLine(rightLine.px, rightLine.py, midX, midY, perpDx, perpDy).distance
    var widthPx = PointToLine(leftLine.px, leftLine.py,
                              rightLine.px, rightLine.py, rightLine.dx, rightLine.dy).distance
    var symPx = Math.abs(leftDistPx - rightDistPx)

    // 8. 像素精度(系数管理器: 面N_像素精度) 换算毫米
    var precision = GetFloatVar("面" + faceNo + "_像素精度")
    if (!precision || precision <= 0) precision = 0.02   // 兜底默认像素精度
    var heightMm = heightPx * precision
    var widthMm  = widthPx * precision
    var symMm    = symPx * precision

    // 9. 可视化
    DrawLine(baseLineL.px - baseDx * 600, baseLineL.py - baseDy * 600,
             baseLineL.px + baseDx * 600, baseLineL.py + baseDy * 600, 0x00FF00, 3)
    DrawLine(baseLineR.px - baseDx * 600, baseLineR.py - baseDy * 600,
             baseLineR.px + baseDx * 600, baseLineR.py + baseDy * 600, 0x00FF00, 3)
    DrawLine(midX - perpDx * 2000, midY - perpDy * 2000,
             midX + perpDx * 2000, midY + perpDy * 2000, 0xFFFF00, 2)
    DrawCross(vertex.x, vertex.y, 0xFF0000, 15)
    DrawCross(baseLeft.x, baseLeft.y, 0xFF00FF, 12)
    DrawCross(baseRight.x, baseRight.y, 0xFF00FF, 12)
    DrawPoint(leftLine.px, leftLine.py, 0x00FFFF)
    DrawPoint(rightLine.px, rightLine.py, 0x00FFFF)
    DrawText(20, 40,
        "H=" + heightMm.toFixed(3) + " W=" + widthMm.toFixed(3) + " Sym=" + symMm.toFixed(3) + "mm",
        0xFFFF00, 0.9)

    // 10. 返回结果(发送 PLC 与 MQTT); 关键点为像素坐标
    return {
        ok: true,
        message: "高度=" + heightMm.toFixed(3) + " 宽度=" + widthMm.toFixed(3)
                 + " 对称度=" + symMm.toFixed(3),
        height: heightMm,
        width: widthMm,
        symmetry: symMm,
        topPoint:           { x: vertex.x,     y: vertex.y },
        baseLineLeftPoint:  { x: baseLeft.x,   y: baseLeft.y },
        baseLineRightPoint: { x: baseRight.x,  y: baseRight.y },
        leftPoint:          { x: leftLine.px,  y: leftLine.py },
        rightPoint:         { x: rightLine.px, y: rightLine.py }
    }
}

